window.EPI_CO.push(
  { id: "c_arzesh_elm", fa: "ارزش علم (ارزش‌سنجی معرفت)", en: "Value of knowledge / epistemic evaluation", def: "مسئلهٔ میزان مطابقت معرفت حصولی با واقعیت؛ این ارزش‌سنجی فقط در قلمرو تصدیقات مطرح است.", secs: ["s38"], vs: ["c_sedq_marefat"], crit: "آیا پرسش این است که «این فهم چه اندازه با واقع مطابق است؟» و موضوعش یک تصدیق است؟", conf: "سنجیدن ارزش یک تصور یا جملهٔ انشایی بر حسب صدق و کذب.", ex: "پرسش از این‌که «آب در ۱۰۰ درجه می‌جوشد» چه اندازه با واقع مطابق است.", st: ["st_grade"] },
  { id: "c_sedq_marefat", fa: "صدق معرفت‌شناختی", en: "Epistemic truth (correspondence)", def: "مطابقت فهم (تصدیق) با واقعیت نفس‌الامری، اعم از مادی، ذهنی و ملازمات؛ عدم مطابقت «کذب» است. فارغ از نیت و باور گوینده و صرفاً ناظر به تطابق مفاد گزاره با نفس‌الامر.", secs: ["s38"], vs: ["c_sedq_akhlaqi", "c_kezb"], crit: "آیا داوری فقط به مفاد گزاره و واقع نگاه می‌کند، بی‌اعتنا به این‌که گوینده به آن باور دارد یا نه؟", conf: "کاذب دانستن گزاره‌ای چون گوینده‌اش به آن باور ندارد (خلط با صدق اخلاقی).", ex: "شهادت زبانی منافقان به رسالت پیامبر از حیث واقعیت عینی صادق است (s38).", st: ["st_grade", "st_naql"] },
  /* c_kezb: با تعریفِ هم‌شناسه در epi_st_a.js ادغام شد (۲۰۲۶-۱۰-۱۴، WORKLOG 42) — محتوای هر دو آن‌جاست؛ تعریفِ دوگانه بی‌صدا جای اولی را می‌گرفت */
  /* c_sedq_akhlaqi: با تعریفِ هم‌شناسه در epi_st_a.js ادغام شد (۲۰۲۶-۱۰-۱۴، WORKLOG 42) — محتوای هر دو آن‌جاست؛ تعریفِ دوگانه بی‌صدا جای اولی را می‌گرفت */
  /* c_nafsolamr: با تعریفِ هم‌شناسه در epi_st_a.js ادغام شد (۲۰۲۶-۱۰-۱۴، WORKLOG 42) — محتوای هر دو آن‌جاست؛ تعریفِ دوگانه بی‌صدا جای اولی را می‌گرفت */
  { id: "c_tojih", fa: "توجیه", en: "Justification", def: "اقامهٔ دلیل و تبیین وجه صدق یک تصدیق تا اعتبار معرفتی آن ثابت شود.", secs: ["s38", "s40"], vs: ["c_mabnagarayi"], crit: "آیا برای تصدیق پاسخی به «چرا صادق است؟» ارائه شده که به دلیل یا پایهٔ بدیهی برسد؟", conf: "یکی گرفتن احساس اطمینان یا اجماع با توجیه.", ex: "توجیه «جهان بیرون هست» با ترکیب احساس بینایی و اصل علیت (s46).", st: ["st_grade"] },
  { id: "c_badihi_tasdiqi", fa: "تصدیق بدیهی", en: "Self-evident (basic) judgement", def: "قضیه‌ای که پذیرش و تصدیق آن نیازمند استدلال و ابتنا بر گزاره‌های دیگر نیست؛ دو قسم دارد: اولی (اولیات) و ثانوی (وجدانیات).", secs: ["s39", "s28"], vs: ["c_nazari_tasdiqi", "c_avvaliyat", "c_vejdaniyat"], crit: "یکی از دو آزمون: صرف تصور اجزا کافی است (اولی) یا یافت حضوری حالت حاضر در خودم (وجدانی).", conf: "بدیهی پنداشتن آنچه آشنا، پرتکرار یا مورد اجماع است.", ex: "«کل از جزء خود بزرگ‌تر است»؛ «من شاد هستم» (s39).", st: ["st_badihi", "st_grade"] },
  { id: "c_nazari_tasdiqi", fa: "تصدیق نظری", en: "Inferential (non-basic) judgement", def: "تصدیقی که علم حضوری مستقیم به متعلقش نیست و از راه پیوند تصدیق‌های معلوم (استدلال/استنتاج) حاصل می‌شود؛ یقین در آن فقط با ارجاع استدلالی به بدیهیات به دست می‌آید. بیشتر دانش‌های بشری از این سنخ‌اند.", secs: ["s40", "s28"], vs: ["c_badihi_tasdiqi"], crit: "آیا برای پذیرش آن به مقدمه، مشاهده، گزارش، حافظه یا تعمیم نیاز است؟", conf: "کاذب دانستن تصدیق نظریِ به بدیهی نرسیده؛ چنین تصدیقی ظنی و مراتب‌دار است.", ex: "«چوب درون آب شکسته است»، «دوستم اندوهگین است».", st: ["st_badihi", "st_route", "st_grade"] },
  { id: "c_avvaliyat", fa: "اولیات (بدیهیات اولی)", en: "Primary self-evident propositions (analytic)", def: "قضایایی که صرف تصور دقیق موضوع، محمول و نسبت حکمیه برای تصدیقشان کافی است؛ ذهن رابطهٔ مفاهیم را با علم حضوری درون خود می‌یابد و بی‌واسطه حکم می‌کند؛ از جمله گزاره‌های تحلیلی. اصل علیت نیز در s46 قضیهٔ اولی عقلی شمرده شده است.", secs: ["s39", "s46"], vs: ["c_vejdaniyat"], crit: "آیا بدون هیچ مشاهده، گزارش یا حالت درونی، فقط با فهم معنای اجزا، حکم پذیرفته می‌شود؟", conf: "اولی دانستن گزاره‌ای که فقط برای ما بسیار آشناست (مانند قواعد تجربی پرتکرار).", ex: "«کل از جزء خود بزرگ‌تر است»؛ «مفهوم انسان کلی است» (s39).", st: ["st_badihi", "st_aql", "st_grade"] },
  { id: "c_vejdaniyat", fa: "وجدانیات (بدیهیات ثانوی)", en: "Introspective self-evident propositions", def: "قضایایی که افزون بر تصور اجزا، تصدیقشان متوقف بر علم حضوری مضاعف به حالات، عواطف یا افعال نفسانی است؛ از حیث قطعیت هم‌پایهٔ اولیات و خطاناپذیرند. به‌تنهایی قضیهٔ کلی نمی‌دهند.", secs: ["s39", "s46"], vs: ["c_avvaliyat"], crit: "آیا حکم، گزارش حالت، عاطفه یا فعلی است که همین حالا در خودِ گوینده حاضر است و آن را بی‌واسطه می‌یابد؟", conf: "وجدانی دانستن حکم دربارهٔ حال دیگران یا دربارهٔ علت و محل احساس خود.", ex: "«من شاد هستم»؛ علم به اراده و تفکر خود (s39).", st: ["st_badihi", "st_shohud", "st_hiss"] },
  { id: "c_madde", fa: "مادهٔ استدلال", en: "Matter (content) of an argument", def: "مقدمات و تصدیقات پایه‌ای که استدلال از آن‌ها تشکیل می‌شود؛ برای یقین باید یا خود بدیهی (اولی یا وجدانی) باشند یا با سلسله‌مراتب به بدیهیات منتهی شوند.", secs: ["s40", "s44"], vs: ["c_surat"], crit: "پرسش «این مقدمه از کجا آمده و به کدام بدیهی می‌رسد؟»", conf: "سنجیدن فقط درستی منطقی استدلال و غفلت از صدق مقدمات.", ex: "در استدلال گذر به جهان خارج: احساس بینایی (وجدانی) و اصل علیت (اولی) (s46).", st: ["st_aql", "st_grade"] },
  { id: "c_surat", fa: "صورت استدلال", en: "Form of an argument", def: "قالب، ساختار و چینش منطقی مقدمات؛ باید عقلاً معتبر و نتیجه‌بخش باشد، مانند شکل قیاس که عقل تلازم مقدمات و نتیجه را با درک حضوری می‌یابد. قالب‌هایی چون استقرا رابطهٔ منطقی ضروری تولید نمی‌کنند و یقین‌آور نیستند.", secs: ["s40"], vs: ["c_madde", "c_istiqra"], crit: "اگر همهٔ مقدمات صادق باشند، آیا نتیجه ضرورتاً صادق است؟", conf: "معتبر دانستن هر استدلالی که «منطقی به نظر می‌رسد».", ex: "قیاس معتبر در برابر تعمیم استقرائی (s40).", st: ["st_aql", "st_grade"] },
  { id: "c_qiyas", fa: "قیاس", en: "Syllogism / deduction", def: "شکلی از استدلال که در آن عقل رابطهٔ تلازم میان مقدمات و نتیجه را با درک حضوری می‌یابد؛ نمونهٔ صورت معتبر و یقین‌آور.", secs: ["s40"], vs: ["c_istiqra"], crit: "نتیجه از مقدمات به ضرورت لازم می‌آید.", conf: "قیاس نامیدن استدلالی که یکی از مقدماتش خود حاصل استقراست و پس یقینی‌اش پنداشتن.", ex: "«این احساس علتی بیرون از ارادهٔ من دارد ... پس علتی عینی هست» (s46).", st: ["st_aql"] },
  { id: "c_yaqin", fa: "یقین", en: "Certainty", def: "درجهٔ یک (صدق یقینی) در مقیاس اعتبار؛ در تصدیق نظری تنها وقتی حاصل است که ماده صادق و منتهی به بدیهی و صورت معتبر باشد؛ بدیهیات به سبب ابتنا بر علم حضوری یقینی‌اند.", secs: ["s40", "s39", "s72"], vs: ["c_zann"], crit: "ماده و صورت هر دو یقینی؟ یا خود بدیهی/حضوری است؟", conf: "یکی گرفتن احساس روانیِ اطمینان با یقین معرفتی؛ تصدیق لزوماً یقین نیست (s27).", ex: "برهان؛ استقراء تام؛ خبر متواتر (s44، s50، s48).", st: ["st_grade", "st_conflict"] },
  { id: "c_zann", fa: "ظن (معرفت غیریقینی)", en: "Probable belief / opinion", def: "تصدیقی با درجهٔ اعتبار میان صفر و یک که بر حساب احتمالات استوار است؛ جزوه از «ظنی»، «گمان» و «غیریقینی» برای آن استفاده می‌کند و در عمل، عقل حکم به عمل بر پایهٔ احتمال بالاتر می‌دهد.", secs: ["s40", "s52", "s53", "s72", "s80"], vs: ["c_yaqin"], crit: "آیا زنجیرهٔ توجیه جایی پیوند غیرقیاسی یا مقدمهٔ غیربدیهی دارد؟", conf: "بی‌ارزش دانستن هر ظن؛ یا یقینی شمردن ظن قوی.", ex: "خبر واحد موثق؛ استقراء ناقص؛ یادآوری شایعه («گمانی ناپایدار») (s48، s50، s52).", st: ["st_grade", "st_conflict"] },
  { id: "c_tashkik_etebar", fa: "اعتبار تشکیکی (مراتب‌دار)", en: "Graded epistemic validity", def: "اعتبار معرفتی امری مراتب‌دار است: ارزش صدق گزاره‌ها بازه‌ای میان صفر (کذب یقینی) تا یک (صدق یقینی) دارد و بر پایهٔ حساب احتمالات تعیین می‌شود.", secs: ["s40"], vs: ["c_yaqin"], crit: "به‌جای «درست/غلط»، عددی میان ۰ و ۱ داده می‌شود.", conf: "دوقطبی دیدن اعتبار.", ex: "تصدیق نظری‌ای که به بدیهیات ختم نشود لزوماً کاذب نیست (تکمیل درس ۸).", st: ["st_grade"] },
  { id: "c_hesab_ehtemal", fa: "حساب احتمالات", en: "Probability calculus", def: "مبنای تعیین درجهٔ اعتبار تصدیقات غیریقینی؛ از منظر آن، ارزش استقراء ناقص حتی با افزایش شواهد به یقین نمی‌رسد.", secs: ["s40", "s50"], vs: [], crit: "آیا درجه از سنجش احتمال (شمار، استقلال و قوت شواهد) به دست آمده است؟", conf: "پنداشتن این‌که انباشت شواهد سرانجام یقین می‌سازد.", ex: "ارزش معرفتی استقراء ناقص (s50).", st: ["st_grade", "st_istiqra"] },
  { id: "c_mabnagarayi", fa: "مبناگرایی", en: "Foundationalism", def: "ساختار نظام معرفتی که در آن تصدیقات نظری با درجات مختلف احتمال یا قطعیت بر پایه‌های اولیه (بدیهیات) استوار می‌شوند.", secs: ["s40"], vs: ["c_tojih"], crit: "آیا زنجیرهٔ توجیه به پایه‌هایی بی‌نیاز از توجیه ختم می‌شود؟", conf: "پنداشتن این‌که مبناگرایی همهٔ باورها را یقینی می‌کند؛ در بیان جزوه روبناها می‌توانند ظنی باشند.", ex: "نمودار سلسله‌مراتب فصل ۱۰: بدیهیات (پایه‌ها) و نظریات (روبناها).", st: ["st_grade"] },
  { id: "c_hokm_amali", fa: "حکم عقل در ساحت عمل", en: "Practical rationality under uncertainty", def: "در ساحت عمل، عقل حکم می‌کند که رفتار انسان بر اساس معرفت موجه و ترجیح احتمال بالاتر شکل گیرد.", secs: ["s40"], vs: ["c_zann"], crit: "آیا تصمیم بر پایهٔ گزینهٔ موجه‌تر و محتمل‌تر گرفته شده، نه بر پایهٔ انتظار یقین؟", conf: "بازایستادن از هر عملی تا رسیدن به یقین.", ex: "تصمیم اعتباری بر پایهٔ ارزیابی ظنی ولی معتبر وثیقه (ساخته سامانه).", st: ["st_grade"] },
  { id: "c_obur_birun", fa: "گذر از علم حضوری به واقعیت خارجی", en: "Inference from inner experience to the external world", def: "شناخت جهان خارج از ترکیب قضایای وجدانی (مانند احساس بینایی حضوری) با قضایای اولی عقلی (مانند اصل علیت: این احساس علتی بیرون از ارادهٔ من دارد) به دست می‌آید؛ وجدانیات به‌تنهایی کلیت نمی‌دهند و اولیات به‌تنهایی در روابط صرف مفاهیم (ریاضیات محض) می‌مانند.", secs: ["s46"], vs: ["c_vejdaniyat", "c_avvaliyat"], crit: "آیا حکم دربارهٔ جهان بیرون به یک داده وجدانی و یک اصل اولی قابل تحلیل است؟", conf: "پنداشتن این‌که اشیای بیرونی «مستقیم» و بی‌استدلال دانسته می‌شوند.", ex: "نمودار چهارمرحله‌ای s46: یافت وجدانی ← اصل عقلی ← استنتاج ← شناخت واقعیت عینی.", st: ["st_hiss", "st_aql", "st_grade"] },
  { id: "c_hekayatgari", fa: "ویژگی دوگانهٔ مفهوم (حضور و حکایت)", en: "Dual aspect of concepts", def: "مفهوم ذهنی از یک سو نزد نفس حاضر است (معلوم به علم حضوری) و از سوی دیگر خاصیت حکایت‌گری کلی از خارج دارد؛ راه گذر از درون به بیرون در همین ویژگی دوگانه است.", secs: ["s46"], vs: ["c_obur_birun"], crit: "تمایز «داشتن مفهوم» (حضوری) از «آنچه مفهوم از آن حکایت می‌کند» (حصولی).", conf: "یکی گرفتن خطاناپذیری حضور مفهوم با درستی حکایت آن از خارج.", ex: "مفهوم «چوب کج» در ذهن حاضر است؛ حکایتش از چوب بیرونی می‌تواند نادرست باشد.", st: ["st_hiss"] },
  { id: "c_estedlal_nakhodagah", fa: "استدلال ناخودآگاه (پنهان)", en: "Unconscious inference", def: "استدلال‌هایی که ذهن بی‌آن‌که متوجه باشد انجام می‌دهد: هم برای اثبات جهان مادی (s46) و هم در تصدیقات حسی که به حکم عادت علت صورت حسی را به خود شیء نسبت می‌دهند (s43)؛ خطای حسی مغالطه در همین استدلال‌هاست.", secs: ["s43", "s46", "s19"], vs: ["c_khata_hissi"], crit: "آیا میان «آنچه حس کردم» و «آنچه دربارهٔ شیء حکم کردم» حلقه‌ای از فرض و استنتاج هست که آگاهانه طی نشده؟", conf: "انتساب خطا به اندام حسی به‌جای استنتاج.", ex: "چوب در آب (s43)؛ پانوشت: «the psychic acts of ordinary perception as unconscious conclusions».", st: ["st_hiss"] },
  { id: "c_rah", fa: "راه معرفت", en: "Source / way of knowing", def: "روش و طریقی که انسان به وسیلهٔ آن به شناختی معتبر نائل می‌شود؛ راه‌های اصلی: شهود، حس، تعقل، نقل، استناد به معرفت دیگران، تجربه، یادآوری (و استقراء که جداگانه بررسی شده است).", secs: ["s42", "s50"], vs: [], crit: "پاسخ به «از کجا می‌دانم؟»", conf: "خلط راه‌ها، مثلاً نقل را حس یا استقراء را تجربه پنداشتن.", ex: "نقشهٔ کلان فصل ۱۱: همهٔ راه‌ها در نهایت به علم حضوری و اولیات عقلی بازمی‌گردند.", st: ["st_route"] },
  { id: "c_shohud", fa: "شهود", en: "Presential intuition (knowledge by presence)", def: "همان علم حضوری (نه اصطلاح خاص عرفانی)؛ چون خودِ معلوم بی‌واسطه نزد عالم حاضر است، «راه» نامیدنش تسامح است؛ ذاتاً معتبر و خطاناپذیر است، اما فقط خودِ یافت، نه تفسیرهای ذهنی برآمده از آن.", secs: ["s42", "s72"], vs: ["c_hiss"], crit: "آیا متعلق، چیزی است که خودش (نه صورتش) در من حاضر است؟", conf: "شهود نامیدن الهام یا حدس دربارهٔ امور بیرونی؛ یا گسترش اعتبار مطلق شهود به تعبیر آن.", ex: "یافت درد، ترس، اراده؛ شهود فطری ضعیف فقر وجودی به خدا (s72).", st: ["st_shohud", "st_route"] },
  { id: "c_tasamoh_rah", fa: "تسامح در «راه» نامیدن شهود", en: "Loose usage of 'way' for intuition", def: "در علم حضوری مسیری پیموده نمی‌شود، زیرا معلوم بی‌واسطه حاضر است؛ پس اطلاق «راه» بر شهود فقط برای مقایسه با دیگر روش‌هاست.", secs: ["s42"], vs: ["c_shohud", "c_rah"], crit: "آیا میان عالم و معلوم واسطه و مسیری هست؟ اگر نه، «راه» به معنای دقیق نیست.", conf: "پنداشتن این‌که شهود مثل حس، ابزار و شرایط بیرونی دارد.", ex: "s42.", st: ["st_route", "st_shohud"] },
  { id: "c_hiss", fa: "شناخت حسی (راه حس)", en: "Sense perception", def: "نخستین راه دستیابی به تصورات و تصدیقات حسی، مشروط به سلامت ابزارهای درونی (اعصاب و مغز) و فراهم بودن شرایط بیرونی (مانند نور)؛ در تصدیقات حسی خطا ممکن است ولی خطا در استدلال پنهان است نه احساس؛ با کنترل شرایط به یقین نزدیک می‌شود.", secs: ["s43", "s72"], vs: ["c_shohud", "c_khata_hissi"], crit: "آیا تصدیق دربارهٔ شیء بیرونی است و از دیدن/شنیدن/لمس خودِ من آمده؟", conf: "یکی گرفتن «دیدم» با «چنین است».", ex: "چوب در آب (s43)؛ در دین: حس مجرای دریافت معجزات و شنیدن روایات (s72).", st: ["st_hiss", "st_route"] },
  { id: "c_sharayet_hiss", fa: "شرایط درونی و بیرونی ادراک حسی", en: "Conditions of perception", def: "سلامت ابزارهای درونی (مانند اعصاب و مغز) و فراهم بودن شرایط بیرونی (مانند نور) که تحقق شناخت حسی مشروط به آن‌هاست و کنترلشان تصدیق حسی را به یقین نزدیک می‌کند.", secs: ["s43"], vs: ["c_hiss"], crit: "آیا اندام و دستگاه عصبی سالم و نور، فاصله و میانجی مناسب بوده؟", conf: "نادیده گرفتن میانجی (آب، صفحهٔ نمایش، اسکن).", ex: "آب به‌عنوان میانجی در مثال چوب کج.", st: ["st_hiss"] },
  { id: "c_khata_hissi", fa: "خطای حسی", en: "Perceptual error", def: "خطایی که در تصدیقات حسی رخ می‌دهد و ناشی از مغالطه در استدلال‌های ناخودآگاه ذهن بر پایهٔ عادت است، نه خودِ احساس مستقیم.", secs: ["s43", "s21", "s19"], vs: ["c_estedlal_nakhodagah"], crit: "آیا با صریح کردن فرض عادتی، علت واقعیِ متفاوتی برای همان صورت حسی پیدا می‌شود؟", conf: "«چشمم اشتباه کرد».", ex: "چوب کج در آب؛ علت واقعی شکست نور (پانوشت: ضریب شکست آب حدود ۱٫۳۳).", st: ["st_hiss"] },
  { id: "c_sheks_noor", fa: "شکست نور", en: "Refraction", def: "پدیدهٔ فیزیکی‌ای که علت واقعی کج دیده شدن چوب در آب است؛ در پانوشت جزوه: ضریب شکست آب ۱٫۳۳ و «چوب صاف وقتی بخشی از آن در آب است و با زاویه‌ای غیر از ۹۰ درجه دیده می‌شود، کج به نظر می‌رسد».", secs: ["s43"], vs: [], crit: "آیا میان چشم و شیء میانجی شفافی با چگالی متفاوت (آب، شیشه) هست و زاویهٔ دید غیر از ۹۰ درجه است؟", conf: "نسبت دادن کجی صورت به خود چوب.", ex: "s43 و پانوشت‌های فصل ۱۰ و ۱۱ (فرادرس، بریتانیکا).", st: ["st_hiss"] },
  { id: "c_aql", fa: "عقل و تعقل", en: "Reason / intellection", def: "عقل ابزار و تعقل راه کسب معرفت است؛ مانند دستگاه پردازشگری عمل می‌کند که مواد اولیه‌اش از علم حضوری تأمین می‌شود؛ چهار کارکرد دارد.", secs: ["s44"], vs: ["c_hiss"], crit: "آیا تصدیق از پردازش مفاهیم و قضایا (نه دریافت مستقیم حسی) آمده است؟", conf: "پنداشتن این‌که عقل بدون مواد حضوری و بدیهی به‌تنهایی معرفت تولید می‌کند.", ex: "s44؛ در دین: اصلی‌ترین ستون اثبات اصول (s73).", st: ["st_aql", "st_route"] },
  { id: "c_karkard_aql", fa: "کارکردهای چهارگانهٔ عقل", en: "Four functions of reason", def: "۱) ادراک مفاهیم کلی، ۲) تجزیه و ترکیب مفاهیم — هر دو تصوری و بی‌صدق‌وکذب — ۳) تصدیق بی‌واسطه (درک بدیهیات)، ۴) استدلال و ترکیب قضایا — هر دو تصدیقی و صدق‌وکذب‌پذیر.", secs: ["s44"], vs: ["c_borhan"], crit: "آیا خروجی یک مفهوم است (۱ و ۲) یا یک حکم (۳ و ۴)؟ حکم بی‌استدلال (۳) یا با استدلال (۴)؟", conf: "داوری صدق دربارهٔ یک تعریف یا مفهوم.", ex: "ادراک مفهوم انسان (۱)؛ تعریف دایره (۲)؛ «کل از جزء بزرگ‌تر است» (۳)؛ قیاس (۴).", st: ["st_aql"] },
  { id: "c_tasdiq_bivasete", fa: "تصدیق بی‌واسطه (کارکرد سوم عقل)", en: "Immediate assent", def: "درک بدیهیات و حکم مستقیم بی‌نیاز از استدلال.", secs: ["s44", "s39"], vs: ["c_badihi_tasdiqi"], crit: "حکم بدون مقدمه پذیرفته می‌شود و یکی از دو آزمون بداهت را می‌گذراند.", conf: "تصدیق بی‌واسطه نامیدن حکمی که فقط سریع و عادتی صادر شده (مثل چوب کج).", ex: "«کل از جزء خود بزرگ‌تر است».", st: ["st_aql", "st_badihi"] },
  { id: "c_borhan", fa: "برهان", en: "Demonstration (burhan)", def: "استدلالی که صورت و ماده‌اش هر دو یقینی باشند؛ اعتبار صوری به‌تنهایی کافی نیست و مقدمات باید به علم حضوری بازگردند.", secs: ["s44", "s40", "s73"], vs: ["c_madde", "c_surat"], crit: "صورت قیاسی معتبر + همهٔ مقدمات بدیهی یا منتهی به بدیهی.", conf: "برهان نامیدن هر استدلال منطقی‌نما.", ex: "براهین عقلی قطعی برای اصول دین (s73).", st: ["st_aql", "st_grade", "st_conflict"] },
  { id: "c_naql", fa: "نقل", en: "Testimony / transmitted report", def: "انتقال معرفت از شخصی به شخص دیگر در جایی که فرد دسترسی مستقیم و حسی به پدیده ندارد؛ دریافت آن بر استدلالی دو‌مقدمه‌ای (صدور خبر، وثاقت و صدق گوینده) استوار است و اعتبارش به درستی معرفت اولیهٔ گوینده و سلامت انتقال وابسته است.", secs: ["s47"], vs: ["c_takhassos"], crit: "آیا محتوا گزارش مشاهده یا رخدادی است که من خود به آن دسترسی نداشته‌ام؟", conf: "یکی گرفتن نقل با تخصص؛ یا یکی گرفتن دیدن متن خبر با دیدن رخداد.", ex: "گزارش شاهد یک رخداد؛ روایات در دین (s73).", st: ["st_naql", "st_route"] },
  { id: "c_sodur", fa: "اصل صدور خبر", en: "Authenticity of attribution", def: "مقدمهٔ نخست استدلال نقل: تصدیق این‌که خبر واقعاً از گوینده صادر شده است.", secs: ["s47"], vs: ["c_vesaqat"], crit: "آیا منبع اصلی (متن، صدا، تأیید گوینده) در دست است؟", conf: "بررسی وثاقت گوینده بدون احراز این‌که واقعاً گفته.", ex: "نقل‌قول منسوب در پیام‌رسان بدون منبع اصلی (ساخته سامانه).", st: ["st_naql", "st_expert"] },
  { id: "c_vesaqat", fa: "وثاقت (ثقه بودن ناقل)", en: "Reliability / trustworthiness of the narrator", def: "مقدمهٔ دوم استدلال نقل: تصدیق وثاقت و صدق کلام گوینده؛ در زنجیرهٔ طولی وثاقت همهٔ واسطه‌ها باید ثابت شود. «موثق» خبر واحدی است که راویانش ثقه‌اند.", secs: ["s47", "s48"], vs: ["c_sodur"], crit: "سابقهٔ راستگویی و دقت، نبود انگیزهٔ کذب، و در دین: توثیق در علم رجال (s73).", conf: "کافی دانستن صداقت گوینده بدون درستی معرفت نخستینش.", ex: "روایات موثق (s80).", st: ["st_naql"] },
  { id: "c_tuli", fa: "نقل طولی (زنجیره‌ای)", en: "Serial (chained) transmission", def: "انتقال خبر از راه زنجیره‌ای از واسطه‌ها؛ اثبات وثاقت همهٔ واسطه‌ها ضروری است و اختلال در یک حلقه کل زنجیره را بی‌اعتبار می‌سازد.", secs: ["s47"], vs: ["c_arzi"], crit: "آیا هر ناقل از ناقل قبلی شنیده است؟", conf: "معتبر دانستن زنجیره‌ای که یک حلقهٔ مجهول دارد.", ex: "«کارمند از همکار حقوقی شنیده که...» (ساخته سامانه).", st: ["st_naql"] },
  { id: "c_arzi", fa: "نقل عرضی (هم‌زمان و مستقل)", en: "Parallel independent reports", def: "نقل‌های هم‌زمان و مستقل از یک رخداد؛ افزایش شمار راویان احتمال انطباق با واقع را تقویت می‌کند.", secs: ["s47"], vs: ["c_tuli", "c_motavater"], crit: "آیا هر گزارش جداگانه و بی‌اتکا به گزارش‌های دیگر به رخداد رسیده است؟", conf: "شمردن بازنشرهای یک منبع به‌عنوان گزارش‌های مستقل.", ex: "پانوشت فصل ۱۱: قضیهٔ هیئت منصفه (افزایش احتمال درستی اکثریت با اندازهٔ گروه).", st: ["st_naql"] },
  { id: "c_sanad", fa: "سند", en: "Chain of transmission (isnad)", def: "وضعیت ناقلان خبر؛ یکی از سه مؤلفهٔ اعتبار خبر. از حیث سند، خبر متواتر یا واحد (موثق/غیرموثق) است.", secs: ["s47", "s48", "s73"], vs: ["c_dalalat", "c_qarine"], crit: "چه کسانی، با چه وثاقتی و در چه شماری نقل کرده‌اند؟", conf: "بسنده کردن به سند و غفلت از دلالت و قرائن.", ex: "s48.", st: ["st_naql"] },
  { id: "c_dalalat", fa: "دلالت", en: "Signification (what the words mean)", def: "دلالت الفاظ خبر بر مقصود؛ دومین مؤلفهٔ اعتبار. از حیث دلالت، کلام نص یا غیرنص است.", secs: ["s47", "s48", "s73"], vs: ["c_sanad"], crit: "آیا الفاظ فقط یک معنا را برمی‌تابند؟", conf: "قطعی دانستن معنایی که فقط یکی از احتمال‌هاست.", ex: "ظاهر «یدالله» (s80).", st: ["st_naql", "st_conflict"] },
  { id: "c_qarine", fa: "قرینه (شواهد جانبی)", en: "Corroborating evidence", def: "شواهد و قرائن جانبی بیرون از خبر که آن را تأیید یا تضعیف می‌کنند؛ سومین مؤلفهٔ اعتبار. خبر باقرینه یا بی‌قرینه است؛ در تعارض غیریقینی‌ها، قوت قرائن ملاک ترازوی عقل است.", secs: ["s47", "s48", "s53"], vs: ["c_sanad", "c_dalalat"], crit: "آیا شاهد مستقلی بیرون از خود خبر آن را تأیید می‌کند؟", conf: "قرینه دانستن تکرار همان خبر.", ex: "هماهنگی روایت با قرآن (s80).", st: ["st_naql", "st_conflict"] },
  { id: "c_motavater", fa: "خبر متواتر", en: "Mass-transmitted report (mutawatir)", def: "خبری که شمار ناقلانش به اندازه‌ای است که تبانی آن‌ها بر کذب عقلاً محال دانسته می‌شود؛ موجب یقین است.", secs: ["s48", "s73"], vs: ["c_vahed"], crit: "آیا تبانی همهٔ این ناقلان مستقل بر دروغ عقلاً محال است؟", conf: "متواتر دانستن خبری که فقط زیاد بازنشر شده ولی منبع واحد دارد.", ex: "پانوشت فصل ۱۳: حدیث غدیر که در طبقهٔ صحابه بیش از ۱۰۰ نفر روایت کرده‌اند.", st: ["st_naql", "st_conflict"] },
  { id: "c_vahed", fa: "خبر واحد", en: "Single-chain report (khabar al-wahid)", def: "خبری که به حد تواتر نرسیده است؛ به «موثق» (دارای راویان ثقه) و «غیرموثق» تقسیم می‌شود.", secs: ["s48"], vs: ["c_motavater"], crit: "شمار ناقلان مستقل برای محال شدن تبانی کافی نیست.", conf: "بی‌اعتبار دانستن هر خبر واحد؛ موثق ظن معتبر می‌دهد.", ex: "s48؛ در دین: بررسی با رجال و درایه (s73).", st: ["st_naql"] },
  { id: "c_movassaq", fa: "خبر موثق / غیرموثق", en: "Reliable / unreliable single report", def: "دو شاخهٔ خبر واحد: موثق آن است که راویانش ثقه‌اند؛ غیرموثق آن است که چنین نیست.", secs: ["s48", "s80"], vs: ["c_vahed"], crit: "وثاقت همهٔ حلقه‌های زنجیره احراز شده است؟", conf: "موثق دانستن زنجیره‌ای که فقط آخرین راوی‌اش ثقه است.", ex: "ترجیح روایات موثق در تعارض (s80).", st: ["st_naql", "st_conflict"] },
  { id: "c_nass", fa: "نص / غیرنص", en: "Explicit / non-explicit text", def: "اگر الفاظ بر معنایی صریح دلالت کنند و احتمال خلاف ندهند، کلام «نص» است؛ اگر احتمالات دیگر را بپذیرد «غیرنص» است و نیازمند قرینه.", secs: ["s48"], vs: ["c_dalalat"], crit: "آیا می‌توان معنای دیگری برای همین الفاظ فرض کرد که با زبان سازگار باشد؟", conf: "یکی گرفتن «ظاهر» با «نص».", ex: "ظاهر «یدالله» غیرنص است و با قرینهٔ برهانی به معنای کنایی حمل می‌شود (s80).", st: ["st_naql", "st_conflict"] },
  { id: "c_bagharine", fa: "باقرینه / بی‌قرینه", en: "Corroborated / uncorroborated", def: "تقسیم خبر از منظر شواهد: «باقرینه» همراه با شواهد تأییدکنندهٔ خارجی است و «بی‌قرینه» بدون آن.", secs: ["s48"], vs: ["c_qarine"], crit: "آیا شاهد بیرونی مستقل در دست است؟", conf: "یکی گرفتن تکرار همان خبر در منابع وابسته با قرینهٔ مستقل.", ex: "s48.", st: ["st_naql"] },
  { id: "c_takhassos", fa: "استناد به تخصص دیگران", en: "Reliance on expertise", def: "پذیرفتن نظر کارشناسی فردی دارای مهارت و روش‌شناسی معین؛ متفاوت با نقل ساده که گزارش مشاهدات حسی عمومی را منتقل می‌کند. اعتبارش بر دو رکن است: اعتبار خود روش معرفتی و درجهٔ تبحر، صلاحیت و پایبندی کارشناس در کاربست آن.", secs: ["s49", "s74"], vs: ["c_naql"], crit: "آیا محتوا داوری‌ای است که فقط با مهارت و روش خاص به دست می‌آید؟", conf: "اعتماد به عنوان و شهرت به‌جای روش و صلاحیت در همان حوزه.", ex: "تقلید از اعلم در فروع دین (s74)؛ گزارش ارزیاب ملک (ساخته سامانه).", st: ["st_expert", "st_route"] },
  { id: "c_istiqra", fa: "استقراء", en: "Induction", def: "سیر ذهن از گزاره‌های جزئی و مشاهدات منفرد به سوی صدور حکمی کلی؛ قالب استقرائی رابطهٔ منطقی ضروری تولید نمی‌کند.", secs: ["s50", "s40"], vs: ["c_qiyas", "c_tajrobe"], crit: "آیا حکم کلی از شمارش موارد جزئی آمده است؟", conf: "یکی گرفتن استقراء با تجربه.", ex: "مرغ راسل (پانوشت فصل ۱۱).", st: ["st_istiqra", "st_route"] },
  { id: "c_istiqra_tam", fa: "استقراء تام", en: "Complete (perfect) induction", def: "بررسی و ارزیابی همهٔ مصادیق و افراد یک مجموعهٔ محدود؛ نتیجه‌اش قطعی و دارای اعتبار صددرصدی است.", secs: ["s50"], vs: ["c_istiqra_naqes"], crit: "مجموعه محدود است و هیچ عضو بررسی‌نشده‌ای نمانده.", conf: "تام دانستن بررسی همهٔ موارد گذشته وقتی حکم شامل آینده است.", ex: "بررسی همهٔ ۲۴ قسط یک وام دوساله (ساخته سامانه).", st: ["st_istiqra"] },
  { id: "c_istiqra_naqes", fa: "استقراء ناقص", en: "Incomplete induction", def: "بررسی فقط بخشی از مصادیق و تعمیم حکم به کل؛ از منظر حساب احتمالات حتی با افزایش شواهد به یقین نمی‌رسد و به‌تنهایی ضرورت و قطعیت کلی را اثبات نمی‌کند.", secs: ["s50", "s51"], vs: ["c_istiqra_tam"], crit: "مجموعه باز یا بزرگ‌تر از نمونهٔ بررسی‌شده است.", conf: "یقینی دانستن تعمیم پس از شواهد بسیار.", ex: "بک‌تست؛ مرغ راسل.", st: ["st_istiqra", "st_grade"] },
  { id: "c_tajrobe", fa: "تجربه", en: "Experiment / experience (in the booklet's sense)", def: "ابزاری عقلی‌ـ‌مشاهده‌ای برای کشف علت پدیده‌ها که در آن داده‌های حسی به اصول عقلی علیت، سنخیت، ضرورت و معیت ضمیمه می‌شوند و با روش «وضع و رفع» شروط و عوامل دخیل آزموده می‌شوند؛ اعتبارش مشروط به عدم دخالت عوامل پنهان و سلامت ابزارهای سنجش است و قطعیتش به پای برهان محض یا شهود نمی‌رسد.", secs: ["s51", "s50"], vs: ["c_istiqra"], crit: "آیا عاملی وضع و رفع شده و اصول عقلی ضمیمه شده‌اند؟", conf: "تجربه دانستن تکرار صرف مشاهدات.", ex: "جوش آب و نقش فشار/ارتفاع (پانوشت فصل ۱۰).", st: ["st_tajrobe", "st_route"] },
  { id: "c_illiyat", fa: "اصل علیت", en: "Principle of causality", def: "در جزوه قضیه‌ای اولی و بدیهی عقلی که در گذر به جهان خارج به کار می‌رود («این احساس نیازمند علتی است خارج از ارادهٔ من») و از اصول عقلیِ ضمیمه‌شده در تجربه است. (صورت عام رایج: هر پدیدهٔ ممکن نیازمند علت است.)", secs: ["s46", "s51"], vs: ["c_sinkhiyat"], crit: "آیا در استدلال از وجود یک پدیده (مثلاً یک احساس) به وجود علتی برای آن حکم شده است؟", conf: "پنداشتن این‌که علیت خود از تجربه آموخته شده (موضع رقیب هیومی؛ نه موضع جزوه).", ex: "s46.", st: ["st_hiss", "st_tajrobe", "st_aql"] },
  { id: "c_sinkhiyat", fa: "اصل سنخیت", en: "Principle of causal homogeneity", def: "از اصول عقلی ضمیمه‌شده در تجربه (s51). جزوه آن را تعریف نمی‌کند؛ در کاربرد رایج فلسفهٔ اسلامی: میان علت و معلول تناسب هست و از علت معین معلول معین پدید می‌آید (پس علت یکسان در شرایط یکسان معلول یکسان دارد).", secs: ["s51"], vs: ["c_illiyat", "c_zarurat"], crit: "آیا از «این علت در موارد آزموده این معلول را داشت» به «در موارد هم‌سنخ نیز همین معلول را دارد» رفته‌ایم؟", conf: "تعمیم به موارد «مشابه» که در عاملی پنهان متفاوت‌اند.", ex: "تعمیم نتیجهٔ آزمایش از موارد آزموده به موارد مشابه.", st: ["st_tajrobe"] },
  { id: "c_zarurat", fa: "اصل ضرورت علّی", en: "Causal necessity", def: "از اصول عقلی ضمیمه‌شده در تجربه (s51). در کاربرد رایج: با تحقق علت تامه، معلول ضرورتاً تحقق می‌یابد.", secs: ["s51"], vs: ["c_sinkhiyat", "c_maiyat"], crit: "آیا حکم شده که با فراهم بودن همهٔ شروط، معلول حتماً رخ می‌دهد؟", conf: "ضروری دانستن معلول وقتی فقط بخشی از شروط (علت ناقصه) فراهم است.", ex: "s51.", st: ["st_tajrobe"] },
  { id: "c_maiyat", fa: "اصل معیت علّی", en: "Simultaneity of cause and effect", def: "از اصول عقلی ضمیمه‌شده در تجربه (s51). در کاربرد رایج: معلول با علت تامه‌اش همراه است و از آن جدا نمی‌شود.", secs: ["s51"], vs: ["c_zarurat"], crit: "آیا حکم شده که معلول همراه علت تامه‌اش است و بی آن باقی نمی‌ماند؟", conf: "پنداشتن این‌که اثر بدون علت تامه‌اش ادامه می‌یابد.", ex: "s51.", st: ["st_tajrobe"] },
  { id: "c_vaz_raf", fa: "روش وضع و رفع", en: "Method of presence and absence (controlled variation)", def: "روشی در تجربه که با گذاشتن (وضع) و برداشتن (رفع) شروط و عوامل دخیل، نقش هر کدام در پیدایش پدیده آزموده می‌شود.", secs: ["s51"], vs: ["c_istiqra"], crit: "آیا عامل در حالی که دیگر عوامل ثابت بودند گذاشته و برداشته شده و تغییر معلول دیده شده است؟", conf: "مقایسهٔ گروه‌هایی که خودشان از جهات دیگر متفاوت‌اند و نامیدن آن وضع و رفع.", ex: "آزمون فیلتر در استراتژی با و بی فیلتر روی همان داده (ساخته سامانه).", st: ["st_tajrobe"] },
  { id: "c_avamel_penhan", fa: "عوامل پنهان", en: "Hidden (confounding) factors", def: "عواملی که در آزمون دیده نشده یا ثابت مانده‌اند و ممکن است در پدیده دخیل باشند؛ اعتبار قانون تجربی همواره مشروط به عدم دخالت آن‌ها (و سلامت ابزار سنجش) است.", secs: ["s51"], vs: ["c_vaz_raf"], crit: "کدام شرط در همهٔ آزمون‌ها ثابت بوده است؟", conf: "مطلق دانستن قانون آزموده‌شده.", ex: "فشار هوا در جوش آب (پانوشت فصل ۱۰).", st: ["st_tajrobe"] },
  { id: "c_taeidgarayi", fa: "تأییدگرایی", en: "Confirmationism", def: "در جزوه، از نظریه‌هایی که «نتوانستند مبنای یقین‌آور تجربه را حل کنند». (زمینه از پانوشت: پس از ناکامی معیار تحقیق‌پذیری در حلقهٔ وین، «لیبرال‌شدن تجربه‌گرایی» و روی آوردن به تأیید تدریجی.)", secs: ["s51"], vs: ["c_ebtalpaziri"], crit: "آیا اعتبار قانون فقط به شمار و قوت موارد تأییدکننده گره خورده است؟", conf: "پنداشتن این‌که تأیید بیشتر = یقین.", ex: "پانوشت فصل ۱۱: SEP «Vienna Circle».", st: ["st_tajrobe"] },
  { id: "c_ebtalpaziri", fa: "ابطال‌پذیری (پوپر)", en: "Falsifiability (Popper)", def: "در جزوه، دیدگاهی که همراه تأییدگرایی «نتوانست مبنای یقین‌آور تجربه را حل کند». (زمینه: پوپر علمی بودن نظریه را به ابطال‌پذیری آن می‌داند؛ پانوشت: ابطال نظریهٔ سطح بالا هرگز با یک مشاهدهٔ منفرد رخ نمی‌دهد.)", secs: ["s51"], vs: ["c_taeidgarayi"], crit: "آیا علمی بودن نظریه به این سنجیده شده که مشاهده‌ای قابل‌تصور است که آن را رد کند؟", conf: "پنداشتن این‌که پوپر مدعی یقین تجربی بود.", ex: "پانوشت فصل ۱۱: SEP «Karl Popper».", st: ["st_tajrobe", "st_istiqra"] },
  { id: "c_yadavari", fa: "یادآوری", en: "Memory (recollection)", def: "راه انتقال و حفظ منظومهٔ دانایی از گذشته به حال که بدون آن انباشت و تداوم معرفت در ساحت‌های حسی، عقلی و نقلی ناممکن می‌شد؛ اعتبارش تابع وثاقت و قوت حافظه (سنجیده با واقعیات بیرونی و اسناد) و درجهٔ اعتبار معرفت نخستین است.", secs: ["s52", "s74"], vs: ["c_naql"], crit: "آیا تصدیق اکنون از حافظه بازیابی شده است؟ راه نخستینش چه بود؟", conf: "روشنی یادآوری را دلیل درستی گرفتن؛ ارتقای شایعهٔ قدیمی به «دانسته».", ex: "یادآوری برهان یقینی (ارزش بالا) در برابر یادآوری شایعه (گمان ناپایدار) (s52).", st: ["st_yad", "st_route"] },
  { id: "c_taaroz", fa: "تعارض معرفت‌ها", en: "Conflict between cognitions", def: "ناسازگاری شناخت‌هایی که از راه‌های گوناگون به دست آمده‌اند؛ داوری در آن با محوریت عقل و امتناع تناقض است: یقینی بر غیریقینی بی‌درنگ مقدم است و میان غیریقینی‌ها ترازوی عقل بر پایهٔ درجهٔ اعتبار و قوت قرائن احتمال برتر را برمی‌گزیند.", secs: ["s53", "s80"], vs: ["c_emtena_tanaqoz"], crit: "آیا دو تصدیق نمی‌توانند هم‌زمان صادق باشند؟", conf: "میانگین گرفتن، یا برنده کردن منبع تازه‌تر.", ex: "خطای باصره در برابر لمس (s53)؛ یدالله در برابر براهین نفی تجسم (s80).", st: ["st_conflict"] },
  { id: "c_emtena_tanaqoz", fa: "امتناع تناقض در واقعیت", en: "Law of non-contradiction", def: "واقعیت متناقض نیست؛ از این رو دو معرفت واقعاً یقینی هرگز با هم تناقض ندارند.", secs: ["s53"], vs: ["c_taaroz"], crit: "اگر دو «یقینی» ناسازگارند، دست‌کم یکی واقعاً یقینی نیست.", conf: "پذیرفتن «هر دو درست‌اند» برای دو گزارهٔ متناقض.", ex: "s53.", st: ["st_conflict"] },
  { id: "c_mehvar_aql", fa: "محوریت عقل (ترازوی عقل)", en: "Centrality of reason in adjudication", def: "عقل داور تعارض‌هاست: یقینی را مقدم می‌کند و میان غیریقینی‌ها بر پایهٔ درجهٔ اعتبار و میزان قوت قرائن احتمال صدق برتر را تعیین می‌کند.", secs: ["s53", "s44"], vs: ["c_taaroz"], crit: "داوری با معیار قطعیت و قرائن، نه تازگی، شهرت یا میل.", conf: "مقدم داشتن ادعای نقلی یا تجربی بر اولیات عقلی.", ex: "نمودار فصل ۱۱: «داوری عقلانی در تعارض‌ها — سنجش ترازوی اعتبار».", st: ["st_conflict"] }
);

/* ───────────── تمرین‌های عینی ───────────── */
window.EPI_DR.push({ id: "d_badihi", st: "st_badihi", title: "بدیهی اولی، بدیهی وجدانی یا نظری؟", items: [
  { q: "«کل از جزء خود بزرگ‌تر است.»", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 0, why: "صرف تصور دقیق کل، جزء و نسبت بزرگ‌تری برای تصدیق کافی است؛ مثال خود جزوه برای اولیات.", sec: "s39" },
  { q: "گوینده دربارهٔ حال خودش: «من اکنون شاد هستم.»", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 1, why: "تصدیق افزون بر تصور اجزا متوقف بر یافت حضوری شادیِ حاضر است؛ مثال خود جزوه برای وجدانیات.", sec: "s39" },
  { q: "«مفهوم انسان کلی است.»", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 0, why: "از تحلیل خود مفهوم برمی‌آید؛ جزوه آن را در کنار «کل از جزء بزرگ‌تر است» از اولیات می‌شمارد.", sec: "s39" },
  { q: "«دوستم اندوهگین است» (از روی حالت چهره‌اش).", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 2, why: "حال دیگری نزد من حاضر نیست؛ پی بردن از روی چهره علم حصولی است.", sec: "s11" },
  { q: "«چوبی که نیمی از آن در آب است شکسته است.»", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 2, why: "حکم دربارهٔ شیء بیرونی حاصل استنتاج پنهان عادتی است؛ فقط صورت دیداری وجدانی است.", sec: "s43" },
  { q: "«من اراده کرده‌ام که بروم» (گزارش گوینده از فعل درونی خودش).", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 1, why: "علم به اراده و تفکر خود از مثال‌های جزوه برای وجدانیات است.", sec: "s39" },
  { q: "اصل علیت، به تعبیر s46: «این احساس نیازمند علتی است خارج از ارادهٔ من». طبق جزوه از کدام قسم است؟", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 0, why: "جزوه اصل علیت را از «قضایای اولی عقلی» می‌شمارد که با وجدانی (احساس بینایی) ترکیب می‌شود؛ خودِ احساس وجدانی است، اما اصل علیت اولی است.", sec: "s46" },
  { q: "کسی که پایش قطع شده: «انگشت پایم درد می‌کند.» کدام جزء وجدانی است؟", opts: ["«درد هست» (اصل احساس درد)", "«محل درد انگشت پاست»", "هر دو جزء", "هیچ‌کدام"], a: 0, why: "اصل احساس حضوری و خطاناپذیر است؛ محل‌یابی حصولی است و این‌جا کاذب.", sec: "s21" },
  { q: "تفاوت اولیات و وجدانیات در چیست؟", opts: ["فقط در نیاز وجدانیات به یافت یک حالت درونی حاضر", "وجدانیات کم‌اعتبارترند چون شخصی‌اند", "اولیات حسی‌اند و وجدانیات عقلی", "وجدانیات نیازمند استدلال‌اند"], a: 0, why: "جزوه تصریح می‌کند تفاوت تنها در همین است و از حیث قطعیت هر دو کامل و خطاناپذیرند.", sec: "s39" },
  { q: "تعریف «دایره» با تکیه بر مفاهیم خط، منحنی و مرکز از کدام قسم علم حصولی است؟", opts: ["تصور بدیهی", "تصور نظری", "تصدیق بدیهی", "تصدیق نظری"], a: 1, why: "تصور نظری از ترکیب تصورات پیشین با فرایند «تعریف» پدید می‌آید؛ مثال خود جزوه.", sec: "s28" },
  { q: "فرایندی که از پیوند دادن تصدیق‌های معلوم حکم تازه‌ای کشف می‌کند چه نام دارد؟", opts: ["تعریف", "استدلال یا استنتاج", "شهود", "تجرید"], a: 1, why: "تصدیق نظری از مسیر استدلال/استنتاج حاصل می‌شود.", sec: "s28" },
  { q: "چرا اولیات و وجدانیات «خطاناپذیر»اند؟", opts: ["چون همه آن‌ها را قبول دارند", "چون بر علم حضوری تکیه دارند", "چون بارها تجربه شده‌اند", "چون در کتاب‌های منطق آمده‌اند"], a: 1, why: "هر دو به دلیل ابتنا بر علم حضوری ارزش معرفتی کامل دارند.", sec: "s39" },
  { q: "«این سند مالکیت جعلی نیست.»", opts: ["بدیهی اولی", "بدیهی وجدانی", "نظری"], a: 2, why: "نه از صرف تصور اجزا برمی‌آید نه گزارش حالت درونی است؛ به بررسی، استعلام یا کارشناسی نیاز دارد. (مثال ساختهٔ سامانه)", sec: "s39" },
  { q: "اگر ذهن فقط وجدانیات داشته باشد، چه چیزی به دست نمی‌آید؟", opts: ["هیچ یقینی", "قضیهٔ کلی", "علم به حالات خود", "علم به اراده"], a: 1, why: "به گفتهٔ جزوه، با تکیهٔ صرف بر وجدانیات قضیهٔ کلی حاصل نمی‌شود.", sec: "s46" }
] });

window.EPI_DR.push({ id: "d_route", st: "st_route", title: "این تصدیق از کدام راه آمده است؟", items: [
  { q: "«دیدم که ماشین به تیر برق خورد.»", opts: ["حس", "نقل", "تخصص دیگران", "تجربه"], a: 0, why: "دریافت مستقیم با حواس خود گوینده.", sec: "s43" },
  { q: "«دوستم تعریف کرد که تصادف را با چشم خودش دیده است.»", opts: ["حس", "نقل", "تخصص دیگران", "یادآوری"], a: 1, why: "گزارش مشاهدهٔ حسی عمومی از شخصی دیگر؛ من دسترسی مستقیم نداشته‌ام.", sec: "s47" },
  { q: "«ارزیاب رسمی ارزش ملک را ۱۲ میلیون برآورد کرده است.»", opts: ["نقل", "تخصص دیگران", "استقراء", "عقل"], a: 1, why: "نظر کارشناسی برآمده از مهارت و روش معین، نه گزارش مشاهدهٔ همگانی.", sec: "s49" },
  { q: "«همهٔ انسان‌ها فانی‌اند؛ سقراط انسان است؛ پس سقراط فانی است.»", opts: ["عقل", "استقراء", "نقل", "تجربه"], a: 0, why: "نتیجه از ترکیب قضایا با استدلال (کارکرد چهارم عقل).", sec: "s44" },
  { q: "«این استراتژی در آینده سودده است، چون در بک‌تست ۸ ساله سودده بود.»", opts: ["تجربه", "استقراء", "عقل", "تخصص دیگران"], a: 1, why: "تعمیم از موارد گذشته به کل بدون وضع و رفع؛ استقراء (ناقص).", sec: "s50" },
  { q: "«با گرم کردن میله، در حالی که بقیهٔ شرایط ثابت بود، طولش زیاد شد و با سرد کردن برگشت؛ پس گرما علت انبساط است.»", opts: ["استقراء", "تجربه", "حس", "نقل"], a: 1, why: "وضع و رفع عامل با ثابت نگه داشتن بقیه و ضمیمهٔ اصل علیت؛ تجربه به معنای جزوه.", sec: "s51" },
  { q: "«یادم هست که قسط ماه پیش را پرداخت کردم.»", opts: ["حس", "یادآوری", "شهود", "نقل"], a: 1, why: "انتقال شناخت گذشته به حال از راه حافظه.", sec: "s52" },
  { q: "گوینده دربارهٔ خودش: «الان می‌ترسم.» (طبق قرارداد سامانه)", opts: ["شهود", "حس", "بدیهی (بی‌نیاز از راه)", "عقل"], a: 0, why: "وجدانی است و بر یافت حضوری تکیه دارد؛ شهود = علم حضوری (s42). قرارداد سامانه: وجدانیات → «شهود»، اولیات → «بدیهی».", sec: "s42" },
  { q: "«کل از جزء خود بزرگ‌تر است.» (طبق قرارداد سامانه)", opts: ["عقل", "بدیهی (بی‌نیاز از راه)", "استقراء", "شهود"], a: 1, why: "اولی است و پذیرشش نیازمند استدلال نیست.", sec: "s39" },
  { q: "فتوای مجتهد اعلم دربارهٔ یک حکم فرعی.", opts: ["نقل", "تخصص دیگران", "عقل", "تجربه"], a: 1, why: "رجوع به کارشناس دینی و تقلید از اعلم در فروع.", sec: "s74" },
  { q: "کدام راه در فهرست راه‌های اصلی s42 نام برده نشده ولی جزوه جداگانه بررسی‌اش کرده است؟", opts: ["یادآوری", "استقراء", "نقل", "تجربه"], a: 1, why: "فهرست s42: شهود، حس، تعقل، نقل، استناد به معرفت دیگران، تجربه، یادآوری؛ استقراء در s50 بررسی شده است.", sec: "s42" },
  { q: "چرا «راه» نامیدن شهود تسامح است؟", opts: ["چون شهود اعتبار ندارد", "چون در علم حضوری معلوم بی‌واسطه حاضر است و مسیری پیموده نمی‌شود", "چون شهود فقط مخصوص عارفان است", "چون شهود همیشه به حس نیاز دارد"], a: 1, why: "پیمودن مسیر در علم حضوری معنا ندارد.", sec: "s42" },
  { q: "«در اخبار تلویزیون گفتند در فلان شهر زلزله آمد.»", opts: ["حس", "نقل", "تخصص دیگران", "استقراء"], a: 1, why: "دیدن صفحهٔ تلویزیون حس است، اما محتوای خبر از راه نقل آمده است.", sec: "s47" },
  { q: "تعریف «راه معرفت» در جزوه کدام است؟", opts: ["هر باوری که در ذهن هست", "روش و طریقی که انسان به وسیلهٔ آن به شناختی معتبر می‌رسد", "فقط حواس پنج‌گانه", "استدلال منطقی"], a: 1, why: "تعریف صریح s42.", sec: "s42" }
] });

window.EPI_DR.push({ id: "d_shohud", st: "st_shohud", title: "هستهٔ حضوری و لایهٔ حصولی", items: [
  { q: "مقصود از «شهود» در بحث راه‌های معرفت چیست؟", opts: ["اصطلاح خاص عرفانی", "همان علم حضوری", "حدس قوی", "الهام دربارهٔ آینده"], a: 1, why: "جزوه تصریح می‌کند شهود همان علم حضوری است، نه اصطلاح خاص عرفانی.", sec: "s42" },
  { q: "اعتبار مطلق و خطاناپذیر شهود شامل کدام است؟", opts: ["خودِ یافت حضوری", "تفسیرهای ذهنی برآمده از یافت", "هر دو", "هیچ‌کدام"], a: 0, why: "این اعتبار مطلق صرفاً به خود یافت حضوری اختصاص دارد.", sec: "s42" },
  { q: "در گرسنگی کاذب کدام بخش خطاپذیر است؟", opts: ["احساس گرسنگی", "حکم «معده خالی است»", "هر دو", "هیچ‌کدام"], a: 1, why: "احساس واقعیتی حضوری است؛ داوری دربارهٔ علت آن (خالی بودن معده) حصولی است.", sec: "s19" },
  { q: "«می‌ترسم، پس خطر واقعی در کار است.» بخش «خطر واقعی است» از کدام سنخ است؟", opts: ["حضوری و خطاناپذیر", "حصولی و خطاپذیر", "اولی", "وجدانی"], a: 1, why: "اصل پدیدار روانی حضوری است، اما این‌که ناشی از خطر واقعی است یا توهم، حصولی است.", sec: "s22" },
  { q: "نام‌گذاری یک حالت درونی (مثلاً «این اضطراب است نه ترس») از کدام ساحت است؟", opts: ["حضوری", "حصولی و وابسته به قرارداد زبانی و آموزش", "بدیهی اولی", "شهود عرفانی"], a: 1, why: "نام‌گذاری حالات بر اساس قراردادهای زبانی و آموزش ساحتی حصولی دارد.", sec: "s22" },
  { q: "در ماجرای حسن بصری در جنگ جمل، خطا کجا بود؟", opts: ["در اصل شنیدن ندا", "در تطبیق و استنباط معنای ندا", "هیچ خطایی نبود", "در حواس ظاهری او"], a: 1, why: "او ندایی شیطانی را شنید و در تطبیق و استنباط معنای آن لغزید.", sec: "s23" },
  { q: "چرا علم حضوری خطاناپذیر است؟", opts: ["چون همیشه شدید است", "چون صورت واسطه‌ای نیست تا مطابقت یا عدم مطابقت معنا یابد", "چون همه آن را دارند", "چون با عقل تأیید شده"], a: 1, why: "خطا عدم مطابقت صورت با واقع است و در حضوری صورتی واسطه نیست.", sec: "s18" },
  { q: "کم‌توجهی به یک احساس درونی چه اثری بر علم حضوری به آن دارد؟", opts: ["آن را کاذب می‌کند", "شدتش را کم می‌کند", "آن را به علم حصولی تبدیل می‌کند", "هیچ اثری ندارد"], a: 1, why: "میزان توجه از عوامل شدت و ضعف علم حضوری است؛ شدت و ضعف، نه صدق و کذب.", sec: "s17" },
  { q: "«احساس می‌کنم همکارم از من دلخور است.» آیا «همکارم دلخور است» شهودی است؟", opts: ["بله، چون احساسش کرده‌ام", "نه، حکمی حصولی دربارهٔ دیگری است", "بله، وجدانی است", "اولی است"], a: 1, why: "حال دیگری حاضر نیست؛ تنها احساس خودم حضوری است.", sec: "s11" },
  { q: "طبق جزوه، علم حضوری به خدا در چه کسانی هست؟", opts: ["فقط عارفان", "در مرتبه‌ای ضعیف در فطرت همگان، حتی منکران", "فقط پیامبران", "هیچ‌کس"], a: 1, why: "s72: شهود نسبت به خداوند در مرتبه‌ای ضعیف در فطرت همگان نهاده شده و در اولیا به مراتب عالی مکاشفه، الهام و وحی می‌رسد؛ s25: اصل فقر وجودی را همگان، حتی منکران، به علم حضوری درمی‌یابند.", sec: "s72" },
  { q: "تفاسیر حصولی کدام دسته از شهودها از خطا ایمن دانسته شده‌اند؟", opts: ["همهٔ عارفان", "وحی و الهام نبوی (با برهان عصمت)", "هیچ‌کدام", "هر شهود شدید"], a: 1, why: "تفاسیر غیرمعصوم ممکن است خطا کنند، مگر در وحی و الهام نبوی که با برهان عصمت ایمن است.", sec: "s72" }
] });

