    var t = X.testB(fw.map(function (c) { var o = {}; for (var k in c) o[k] = c[k]; o.kind = "real"; return o; }), cfg);
    /* محک آزمون ۳ فقط سرانجام واقعی ادعاهاست: آیا ادعای پرچم‌خورده بیشتر نادرست درآمد و سقف‌ها از نرخ پایه دقیق‌ترند؟ */
