    (d.s9 || "").split(/[\n؛;]+/).map(function (x) { return x.trim(); }).filter(function (x) { return x.length > 3; }).slice(0, 5).forEach(function (k) { upsert("knot", k.slice(0, 120), "لبه باز امروز", (trunkN || rootN || {}).id, "science"); });
