      it.choices = texts.map(function (t2, j2) { it.params.forms[ids[j2]] = forms[j2]; return { id: ids[j2], t: ltr(t2) }; }).concat([{ id: ids[3], t: NONE }]).sort(function (x, y) { return x.id < y.id ? -1 : 1; });
      it.answer = decoy ? ids[3] : ids[bad];
