    it.params = { T: T, R2: R2, R3: R3, lab: [lab[0], lab[1], lab[2]], table: table, k2: k2, k3: k3 };
    it.choices = texts.map(function (t, j) { return { id: ids[j], t: t }; }).sort(function (x, y) { return x.id < y.id ? -1 : 1; });
    it.prompt = prompt; it.explain = explain;
