    var it = kc.intake = kc.intake || {}; var q = (A.getProb && A.getProb(kc.src.pid) || { stages: [] }).stages.filter(function (x) { return x.id === kc.src.sid; })[0];
    it.statement = "زمینهٔ کامل (پس از دیدنِ پاسخ): " + kc.src.ctxHeld + "\n\n" + (it.statement || (q && q.q) || "");
