        var calE = A.PSY.selfEst(X.cal.filter(function (c) { return !c.fc; }).map(function (c) { return { at: c.at, ok: c.ok, conf: c.p }; }), true);
        X.est.pOver = calE.pOver; X.est.meanConf = calE.meanConf; X.est.calN = calE.calN || 0;
