    var ids = []; ((s.tour && s.tour.facets) || []).forEach(function (f) { if (f.status !== "skipped") (f.refs || []).forEach(function (r) { if (r.type === "kcase" && ids.indexOf(r.id) < 0) ids.push(r.id); }); });
