    var dtw = dt0.filter(function (w) { return !/^\d/.test(w); }), dt = dtw.length ? dtw : dt0;
    var dm = toksSim(d), ot = toks((others || []).join(" ")), dist = dt.filter(function (w) { return !hit(w, ot); });
