    R.crit = [{ ok: L.length >= 3, t: "دست‌کم ۳ آزمایشِ کامل (پیش‌بینی، مشاهده، نتیجه) — اکنون " + fa(L.length) }, { ok: span >= 14, t: "فاصلهٔ اولین تا آخرین دست‌کم ۱۴ روز — اکنون " + fa(span) + " روز" }];
